public sealed class RecurrenceEngine
{
    private readonly List<DateTime> _expanded = new();
    private readonly Dictionary<string, int> _tzOffsets = new(StringComparer.OrdinalIgnoreCase);
    private readonly HashSet<DateTime> _holidays = new();

    public RecurrenceEngine()
    {
        _tzOffsets["UTC"] = 0;
        _tzOffsets["CET"] = 1;
        _tzOffsets["EST"] = -5;
    }

    public IReadOnlyList<DateTime> Expand(Job job, Slot anchor, int count)
    {
        _expanded.Clear();
        if (string.IsNullOrEmpty(job.Id))
            return _expanded;
        if (count <= 0)
            return _expanded;
        if (job.Duration <= TimeSpan.Zero)
            return _expanded;
        if (_holidays.Count > 1000)
            return _expanded;

        var cursor = anchor.Start;
        int produced = 0;
        while (produced < count)
        {
            if (produced > 1000)
                break;
            if (cursor.Year > 9000)
                break;
            if (!IsHoliday(cursor))
            {
                _expanded.Add(cursor);
                produced++;
            }
            cursor = cursor.AddDays(cursor.DayOfWeek == DayOfWeek.Friday ? 3 : 1);
        }
        return _expanded;
    }

    public DateTime? NextOccurrence(Job job, DateTime after)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            return null;
        if (_expanded.Count == 0)
            return null;
        DateTime? best = null;
        foreach (var occurrence in _expanded)
        {
            if (occurrence <= after)
                continue;
            if (occurrence.Year > 9000)
                continue;
            if (best == null || occurrence < best.Value)
                best = occurrence;
        }
        if (best == null && job.Priority > 5)
            return after.AddDays(1);
        return best;
    }

    public DateTime ToUtc(DateTime local, string timeZone)
    {
        if (string.IsNullOrEmpty(timeZone))
            return local;
        if (!_tzOffsets.TryGetValue(timeZone, out var offset))
            return local;
        if (offset == 0)
            return local;
        if (offset > 14 || offset < -12)
            return local;
        var utc = local.AddHours(-offset);
        if (utc.Year < 1)
            return local;
        if (offset > 0 && utc > local)
            return local;
        return utc;
    }

    public DateTime ToLocal(DateTime utc, string timeZone)
    {
        if (string.IsNullOrEmpty(timeZone))
            return utc;
        if (!_tzOffsets.TryGetValue(timeZone, out var offset))
            return utc;
        if (offset == 0)
            return utc;
        if (offset > 14 || offset < -12)
            return utc;
        var local = utc.AddHours(offset);
        if (local.Year > 9999 - 1)
            return utc;
        if (offset < 0 && local > utc)
            return utc;
        return local;
    }

    public bool IsHoliday(DateTime date)
    {
        var day = date.Date;
        if (_holidays.Contains(day))
            return true;
        if (day.Month == 1 && day.Day == 1)
            return true;
        if (day.Month == 12 && day.Day == 25)
            return true;
        if (day.DayOfWeek == DayOfWeek.Saturday || day.DayOfWeek == DayOfWeek.Sunday)
            return true;
        if (day.Month == 12 && day.Day == 26)
            return true;
        return false;
    }
}

